import { Component, inject } from '@angular/core';

import { db,auth } from '../../../enviroment';
import { addDoc, collection, getDocs, orderBy, limit, query, Firestore, Timestamp } from "@angular/fire/firestore";
import jsPDF from "jspdf";
import autoTable from "jspdf-autotable";
import { Repuesto } from '../../services/repuesto';
import { App } from '../../app';
import { FormControl, FormsModule, ReactiveFormsModule } from '@angular/forms';
import { CommonModule } from '@angular/common';
import { ActivatedRoute, RouterModule, RouterOutlet } from '@angular/router';
import { Auth } from '@angular/fire/auth';
import { Cotizacion, cotizacionService } from '../../services/cotizacion';
import { debounceTime, distinctUntilChanged, finalize, switchMap } from 'rxjs';

import {  getDownloadURL, ref, uploadBytes } from '@angular/fire/storage';
import { Storage } from '@angular/fire/storage';

interface Item {
  id: number;
  codigo: string;
  nombre: string;
  marca?: string;
  precio: number;
  estante?: number;
  cantidad?: number;
  
}

@Component({
  selector: 'app-cotizaciones',
  standalone:true,
  imports: [FormsModule,CommonModule,ReactiveFormsModule, RouterModule, RouterOutlet],
  templateUrl: './cotizaciones.html',
  styleUrls: ['./cotizaciones.css']
})
export class Cotizaciones {

search= new FormControl('');
  
  // Métodos para actualizar estado
 cliente: string = '';
  seleccionados: any[] = [];
  Descuento: number = 0;
  dropdownAbierto: boolean = false;
  showConfig: boolean = false;
  ItemsDisponibles: Item[] = [];
  Cantidad: number = 0;

  private firestore = inject(Firestore); 
  private storage = inject(Storage);   

  constructor(
  private serviceE: App, 
  private serviceC: cotizacionService, 
  private route: ActivatedRoute) {

    this.search.valueChanges.pipe(
          debounceTime(300),
          distinctUntilChanged(),
          switchMap((value) => this.serviceC.buscarRepuesto(value ?? ''))
        ).subscribe((data) => {
          this.ItemsDisponibles = data;
        });
  }


  ngOnInit(): void {
    this.loadRepuestos();
  }

  onBuscar() {
    const query= this.search.value?.trim() ?? '';
    if (query) {
      this.serviceC.buscarRepuesto(query).subscribe(data => this.ItemsDisponibles = data);
     
    } else {
      this.ItemsDisponibles = [];
      this.loadRepuestos();
    }
  }

  isSeleccionado(item: Item): boolean {
  return !!this.seleccionados.find(i => i.id === item.id);
}
  // Toggle dropdown y configuración
  toggleDropdown() {
    this.dropdownAbierto = !this.dropdownAbierto;
  }

  toggleConfig() {
    this.showConfig = !this.showConfig;
  }

  logout() {
    this.serviceE.logout();
  }
loadRepuestos(): void {
    
    this.serviceC.getProductos().subscribe({
      next: data => {
      this.ItemsDisponibles = data;
    },
    error: err => {
      console.error('Error cargando repuestos', err);
    }
  });

      }

  // Seleccionar o deseleccionar item
  toggleItem(item: Item) {
    const index = this.seleccionados.findIndex(i => i.id === item.id);
    if (index >= 0) {
      this.seleccionados.splice(index, 1);
    } else {
      this.seleccionados.push({ ...item, cantidad: 1, total: item.precio });
    }
  
  }
  // Cambiar cantidad y recalcular total
  cambiarCantidad(id: number, cantidad: number) {
    this.seleccionados = this.seleccionados.map(i =>
      i.id === id ? { ...i, cantidad, total: cantidad * i.precio } : i
    );
  }

getCantidad(item: Item): number {
  const sel = this.seleccionados.find(i => i.id === item.id);
  return sel?.cantidad ?? 1; // si no existe, retorna 1 por defecto
}
get cantidad(): number {
  return this.seleccionados.reduce((acc, i) => acc + (i.cantidad ?? 0), 0);
}
  // Calcular totales
 get subtotal(): number {
    return this.seleccionados.reduce((acc, i) => acc + (i.total ?? 0), 0);
  }

   get descuento(): number {
    return this.subtotal * (this.Descuento);
  }

  get total(): number {
    return this.subtotal - this.descuento;
  }

   // Obtener último número de cotización
  // Generar número secuencial de cotización
async generarNumero(): Promise<string> {
  // Crear referencia a la colección
  const cotizacionesRef = collection(this.firestore, 'cotizaciones');

  // Crear consulta para obtener la última cotización
  const q = query(cotizacionesRef, orderBy('timestamp', 'desc'), limit(1));

  // Obtener documentos
  const snap = await getDocs(q);

  if (snap.empty) return 'cot0-1073';

  const last = snap.docs[0].data()['numero'] as string;
  const num = parseInt(last.split('-')[1]) + 1;

  return `cot0-${num}`;
}
// Generar PDF como blob
generarPDFBlob(numero: string): Blob {
  const doc = new jsPDF({ unit: 'pt', format: 'letter' });

  // Generar PDF como blob manteniendo tu formato
 const logo = "data:image/jpeg;base64,";

  // Logo
  const logoWidth = 80;
  const logoHeight = 80;
  const logoX = 40;
  const logoY = 30;
  doc.addImage(logo, 'PNG', logoX, logoY, logoWidth, logoHeight);

  // Nombre empresa
  const textX = logoX + logoWidth + 15;
  const textY = logoY + logoHeight / 2 + 5;
  doc.setFontSize(24);
  doc.text("AUTOMEGAREPUESTOS", textX, textY);

  // Info debajo del nombre
  doc.setFontSize(11);
  doc.text("18111998005838", textX, textY + 20);
  doc.text("Yorito,Yoro, Honduras", textX, textY + 35);

  // Título Cotización
  doc.setFontSize(24);
  doc.text("Cotización", 420, logoY + 30);

  // Datos del cliente
  doc.setFontSize(12);
  doc.text(`Cliente: ${this.cliente}`, 40, logoY + 100);
  doc.text("Proveedor: AUTOMEGAREPUESTOS", 40, logoY + 120);
  doc.text("Vendedor: AUTOMEGAREPUESTOS", 40, logoY + 140);
  doc.text(`Fecha: ${new Date().toLocaleDateString("es-HN")}`, 420, logoY + 100);
  doc.text(`Código cotización: ${numero}`, 420, logoY + 120);

  // Tabla de items
  autoTable(doc, {
    startY: logoY + 170,
    head: [["id", "codigo", "nombre", "marca", "precio", "cantidad", "Total"]],
    body: this.seleccionados.map((it, index) => [
      index + 1,
      it.codigo,
      it.nombre,
      it.marca ?? "",
      it.precio.toFixed(2),
      it.cantidad,
      (it.total ?? it.precio).toFixed(2)
    ]),
    styles: { fontSize: 11, halign: "center" },
    headStyles: { fillColor: [230, 230, 230], fontStyle: "bold" },
    tableWidth: 520,
    margin: { left: 40 }
  });

  const finalY = (doc as any).lastAutoTable.finalY + 20;

  // Totales
  autoTable(doc, {
    startY: finalY,
    head: [["Descripción", "Monto"]],
    body: [
      ["Subtotal", `${this.subtotal.toFixed(2)} L`],
      ["Monto gravado", `${this.subtotal.toFixed(2)} L`],
      ["Descuento", `${this.descuento.toFixed(2)} L`],
      ["Total", `${this.total.toFixed(2)} L`]
    ],
    margin: { left: 300 },
    tableWidth: 250,
    styles: { halign: "right" },
    headStyles: { fillColor: [230, 230, 230] }
  });

  // Footer
  doc.text("Imp Exonerado", 40, (doc as any).lastAutoTable.finalY + 20);
  doc.text(`Descuento: ${this.descuento.toFixed(2)} L`, 40, (doc as any).lastAutoTable.finalY + 40);
  doc.text("Cotización válida por 30 días", 40, (doc as any).lastAutoTable.finalY + 80);
  doc.text("leo1318velasquez@hotmail.es", 40, (doc as any).lastAutoTable.finalY + 100);

  // Devuelve el PDF como blob para subir a Firebase Storage
  return doc.output('blob');
}


// Guardar cotización y subir PDF a Storage
async guardarCotizacion() {
    if (this.seleccionados.length === 0) {
      alert('Seleccione al menos un item para generar la cotización.');
      return;
    }

    try {
      const numero = await this.generarNumero();
      const pdfBlob = this.generarPDFBlob(numero);

      // Subida modular a Storage
      const filePath = `cotizaciones/${numero}.pdf`;
     
       const storageRef = ref(this.storage, filePath);
      await uploadBytes(storageRef, pdfBlob);

      // Obtener URL del PDF
      const pdfURL = await getDownloadURL(storageRef);

      // Guardar en Firestore modular
      await addDoc(collection(this.firestore, 'cotizaciones'), {
        numero,
        cliente: this.cliente,
        proveedor: "AUTOMEGAREPUESTOS",
        fecha: new Date().toLocaleDateString("es-HN"),
        items: this.seleccionados,
        subtotal: this.subtotal,
        cantidad: this.cantidad,
        descuento: this.descuento,
        total: this.total,
        timestamp: Timestamp.fromDate(new Date()),
        archivoURL: pdfURL
      });

      alert('Cotización guardada y PDF subido correctamente.');
    } catch (error) {
      console.error('Error al guardar cotización:', error);
      alert('Ocurrió un error al guardar la cotización.');
    }
  }
getBase64Image(path: string): Promise<string> {
  return fetch(path)
    .then(res => res.blob())
    .then(blob => new Promise(resolve => {
      const reader = new FileReader();
      reader.onloadend = () => resolve(reader.result as string);
      reader.readAsDataURL(blob);
    }));
}
  // Generar PDF
}



